<?php
namespace App\Http\Controllers;
use App\Models\Articulo; use App\Models\Empleado; use App\Models\Periodo; use App\Models\Resguardo; use App\Models\ResguardoArticulo; use App\Models\Ubicacion; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Auth;
class RevisionController extends Controller {
 public function periodos(){ $periodos=Periodo::withCount('resguardos')->orderByDesc('Id_Periodo')->paginate(15); return view('periodos.index',compact('periodos')); }
 public function crearPeriodo(){ return view('periodos.create'); }
 public function guardarPeriodo(Request $r){ $d=$r->validate(['Nombre'=>'required|string|max:50','Fecha_Inicio'=>'required|date']); Periodo::create($d+['Estado'=>'Abierto','status'=>'activo','Estatus'=>'Activo']); return redirect()->route('revision.periodos')->with('ok','Periodo creado correctamente.'); }
 public function seleccionar($periodo){ $periodo=Periodo::findOrFail($periodo); abort_if($periodo->Estado==='Cerrado',403,'El periodo está cerrado.'); $ubicaciones=Ubicacion::where('status','activo')->orderBy('Edificio')->orderBy('Nombre')->get(); $empleados=Empleado::where('Estatus','Activo')->orderBy('Nombre')->get(); return view('revision.select',compact('periodo','ubicaciones','empleados')); }
 public function iniciar(Request $r,$periodo){ $periodo=Periodo::findOrFail($periodo); abort_if($periodo->Estado==='Cerrado',403,'El periodo está cerrado.'); $d=$r->validate(['FkId_Ubicacion'=>'required|exists:ubicaciones,Id_Ubicacion','FkId_Empleado'=>'required|exists:empleados,Id_Empleado']); $res=Resguardo::create($d+['FkId_Periodo'=>$periodo->Id_Periodo,'Fecha_Firma'=>now()->toDateString()]); $articulos=Articulo::where('FkId_Ubicacion',$d['FkId_Ubicacion'])->where('status','activo')->get(); foreach($articulos as $a) ResguardoArticulo::firstOrCreate(['FkId_Resguardo'=>$res->Id_Resguardo,'FkId_Articulo'=>$a->Id_Articulo],['FkId_Ubicacion'=>$a->FkId_Ubicacion]); return redirect()->route('revision.scan',$res); }
 public function scan(Resguardo $resguardo){ $resguardo->load(['periodo','empleado','ubicacion']); abort_if($resguardo->Cerrado || $resguardo->periodo->Estado==='Cerrado',403,'La revisión está cerrada.'); $items=$resguardo->articulos()->with(['articulo.modelo','articulo.marca','articulo.ubicacion'])->orderBy('Revisado')->get(); return view('revision.scan',compact('resguardo','items')); }
 public function buscar(Request $r,Resguardo $resguardo){ $r->validate(['codigo'=>'required|string|max:120']); $codigo=trim($r->codigo); $a=Articulo::with(['modelo','marca','ubicacion'])->where('Codigo_Barras',$codigo)->orWhere('N_Serie',$codigo)->first(); if(!$a) return response()->json(['ok'=>false,'type'=>'not_found','message'=>'Artículo no encontrado.'],404); $expected=ResguardoArticulo::where('FkId_Resguardo',$resguardo->Id_Resguardo)->where('FkId_Articulo',$a->Id_Articulo)->first(); if(!$expected){ return response()->json(['ok'=>false,'type'=>'not_expected','article'=>$this->articleJson($a),'message'=>'El artículo no pertenece a la carga esperada de esta ubicación.']); } if($expected->Revisado){ return response()->json(['ok'=>true,'type'=>'already_reviewed','article'=>$this->articleJson($a),'message'=>'Este artículo ya había sido revisado.']); } if((int)$a->FkId_Ubicacion !== (int)$resguardo->FkId_Ubicacion){ return response()->json(['ok'=>false,'type'=>'wrong_location','article'=>$this->articleJson($a),'actual_location'=>$a->ubicacion?->Nombre,'expected_location'=>$resguardo->ubicacion?->Nombre,'message'=>'Artículo encontrado, pero está registrado en otra ubicación.']); } $expected->update(['Revisado'=>true,'Fecha_Revision'=>now()]); return response()->json(['ok'=>true,'type'=>'reviewed','article'=>$this->articleJson($a),'message'=>'Artículo revisado correctamente.']); }
 private function articleJson(Articulo $a){ return ['id'=>$a->Id_Articulo,'codigo'=>$a->Codigo_Barras,'serie'=>$a->N_Serie,'descripcion'=>$a->Descripcion,'modelo'=>$a->modelo?->Nombre,'marca'=>$a->marca?->Nombre,'imagen'=>($a->modelo?->URL_Imagen ?: $a->URL_Imagen) ? \Illuminate\Support\Facades\Storage::disk('public')->url($a->modelo?->URL_Imagen ?: $a->URL_Imagen) : null]; }
 public function reasignar(Request $r,Resguardo $resguardo,Articulo $articulo){ $r->validate(['confirmacion'=>'accepted']); abort_if($resguardo->Cerrado,403); DB::transaction(function() use($resguardo,$articulo){ $articulo->update(['FkId_Ubicacion'=>$resguardo->FkId_Ubicacion]); $item=ResguardoArticulo::where('FkId_Resguardo',$resguardo->Id_Resguardo)->where('FkId_Articulo',$articulo->Id_Articulo)->firstOrFail(); $item->update(['FkId_Ubicacion'=>$resguardo->FkId_Ubicacion,'Revisado'=>true,'Fecha_Revision'=>now(),'Comentarios'=>'Ubicación reasignada durante revisión']); }); return response()->json(['ok'=>true,'message'=>'Ubicación reasignada y artículo marcado como revisado.']); }
 public function cierre(Resguardo $resguardo){ $resguardo->load(['periodo','empleado','ubicacion']); $items=$resguardo->articulos()->with(['articulo.modelo','articulo.ubicacion'])->get(); return view('revision.close',compact('resguardo','items')); }
 public function cerrarResguardo(Request $r,Resguardo $resguardo){ $r->validate(['Observaciones'=>'nullable|string|max:500']); abort_if($resguardo->Cerrado,403); $resguardo->update(['Cerrado'=>true,'Fecha_Cierre'=>now(),'Observaciones'=>$r->Observaciones]); return redirect()->route('resguardo.print',$resguardo)->with('ok','Resguardo cerrado correctamente.'); }
 public function imprimir(Resguardo $resguardo){ $resguardo->load(['periodo','empleado.area','empleado.puesto','ubicacion','articulos.articulo.modelo','articulos.articulo.ubicacion']); return view('resguardos.print',compact('resguardo')); }
 public function cerrarPeriodo(Request $r,Periodo $periodo){ abort_unless(Auth::user()?->rol?->Nombre === 'Administrador',403,'Solo el Administrador puede cerrar periodos.'); abort_if($periodo->Estado==='Cerrado',403); $pendientes=$periodo->resguardos()->where('Cerrado',false)->count(); if($pendientes>0) return back()->withErrors(['clave'=>'No se puede cerrar: todavía hay resguardos abiertos.']); $periodo->update(['Estado'=>'Cerrado','Fecha_Cierre'=>now()->toDateString()]); return redirect()->route('revision.periodos')->with('ok','Periodo cerrado y bloqueado.'); }
 public function historico(Request $r){ $resguardos=Resguardo::with(['periodo','empleado','ubicacion'])->when($r->ubicacion,fn($q)=>$q->where('FkId_Ubicacion',$r->ubicacion))->when($r->empleado,fn($q)=>$q->where('FkId_Empleado',$r->empleado))->when($r->area,fn($q)=>$q->whereHas('empleado',fn($q)=>$q->where('FkId_Area',$r->area)))->orderByDesc('Id_Resguardo')->paginate(20)->withQueryString(); $ubicaciones=Ubicacion::orderBy('Nombre')->get(); $empleados=Empleado::orderBy('Nombre')->get(); $areas=\App\Models\Area::orderBy('Nombre')->get(); return view('revision.history',compact('resguardos','ubicaciones','empleados','areas')); }
}
